import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]         = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState(null);
  const [pendingRegister, setPendingRegister] = useState(null);
  const [paidIds, setPaidIds]       = useState([]);

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get('http://localhost:5000/api/attendee/events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchEvents(); }, []);

  const handleRegister = (id) => setPendingRegister(id);

  const handlePay = async () => {
    try {
      const token = localStorage.getItem('token');
      // first register
      await axios.post(
        'http://localhost:5000/api/attendee/register',
        { eventId: pendingRegister },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      // then pay
      await axios.post(
        `http://localhost:5000/api/attendee/pay/${pendingRegister}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setPaidIds(ids => [...ids, pendingRegister]);
      setPendingRegister(null);
    } catch {
      alert('Payment failed');
    }
  };

  const upcoming   = events.filter(e => !paidIds.includes(e._id));
  const registered = events.filter(e => paidIds.includes(e._id));

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming Events */}
        <section>
          <h3>Upcoming Events</h3>
          {loading ? <p>Loading…</p> :
           error   ? <p style={{ color:'red' }}>{error}</p> :
           upcoming.length === 0
             ? <p>No upcoming events.</p>
             : <ul>
                 {upcoming.map(evt => (
                   <li key={evt._id} style={{ margin: '1rem 0' }}>
                     <strong>{evt.title}</strong> – {new Date(evt.date).toLocaleString()}<br/>
                     {pendingRegister === evt._id
                       ? <button className="btn" onClick={handlePay}>Pay Now</button>
                       : <button className="btn" onClick={() => handleRegister(evt._id)}>
                           Register
                         </button>
                     }
                   </li>
                 ))}
               </ul>
          }
        </section>

        {/* Registered Events */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Registered Events</h3>
          {registered.length === 0
            ? <p>No paid events yet.</p>
            : <ul>
                {registered.map(evt => (
                  <li key={evt._id} style={{ margin: '1rem 0' }}>
                    <strong>{evt.title}</strong> – {new Date(evt.date).toLocaleString()}<br/>
                    <a href={evt.sessionLink || '#'} className="btn">
                      {evt.sessionLink ? 'Join Session' : 'Session TBA'}
                    </a>
                  </li>
                ))}
              </ul>
          }
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
